3	interface TextLeaf {
4	  text: string;
5	  [mark: string]: unknown;
6	}
7	
8	interface ElementNode {
9	  children: unknown[];
10	  [prop: string]: unknown;
11	}
12	
13	const isTextLeaf = (node: unknown): node is TextLeaf =>
14	  typeof (node as { text?: unknown }).text === "string";
15	
16	const isElement = (node: unknown): node is ElementNode =>
17	  Array.isArray((node as { children?: unknown }).children);
18	
19	/** Reference-search the value for `target`, returning its Slate path or null. */
20	const findElementPath = (
21	  nodes: readonly unknown[],
22	  target: unknown,
23	  base: number[]
24	): number[] | null => {
25	  for (const [index, node] of nodes.entries()) {
26	    const here = [...base, index];
27	    if (node === target) return here;
28	    if (!isElement(node)) continue;
29	    const found = findElementPath(node.children, target, here);
30	    if (found !== null) return found;
31	  }
32	  return null;
33	};
34	
35	/** Collect the path of every text leaf descending from `path`. */
36	const collectTextLeafPaths = (node: unknown, path: number[], out: number[][]): void => {
37	  if (isTextLeaf(node)) {
38	    out.push(path);
39	    return;
40	  }
41	  if (isElement(node)) {
42	    for (const [index, child] of node.children.entries()) {
43	      collectTextLeafPaths(child, [...path, index], out);
44	    }
45	  }
46	};
47	
48	const taskIdOfLeaf = (leaf: TextLeaf): string | null => {
49	  const key = Object.keys(leaf).find((k) => k.startsWith("task_") && leaf[k] === true);
50	  return key === undefined ? null : key.slice("task_".length);
51	};
52	
53	/** First `task_<id>` mark id carried by any text leaf under `node`, or null. */
54	const findTaskId = (node: unknown): string | null => {
55	  if (isTextLeaf(node)) return taskIdOfLeaf(node);
56	  if (!isElement(node)) return null;
57	  for (const child of node.children) {
58	    const found = findTaskId(child);
59	    if (found !== null) return found;
60	  }
61	  return null;
62	};
63	
64	const setLeafMarks = (
65	  editor: PlateEditor,
66	  itemPath: number[],
67	  node: unknown,
68	  marks: object
69	): void => {
70	  const leaves: number[][] = [];
71	  collectTextLeafPaths(node, itemPath, leaves);
72	  for (const at of leaves) editor.tf.setNodes(marks, { at });
73	};
74	
75	const unsetLeafMarks = (
76	  editor: PlateEditor,
77	  itemPath: number[],
78	  node: unknown,
79	  keys: string[]
80	): void => {
81	  const leaves: number[][] = [];
82	  collectTextLeafPaths(node, itemPath, leaves);
83	  for (const at of leaves) editor.tf.unsetNodes(keys, { at });
84	};
