86	/**
87	 * Toggle a GFM task checkbox as reviewer feedback (the plan is annotate-only,
88	 * so the toggle is recorded, not written back to source). Flips the item's
89	 * `checked` and tags its text with `task` / `task_<id>` marks the walker reads.
90	 * `taskOriginal` snapshots the pre-toggle state so toggling back to the
91	 * original removes the marks and the feedback entirely.
92	 */
93	export const applyTaskToggle = (editor: PlateEditor, element: unknown): void => {
94	  const itemPath = findElementPath(editor.children, element, []);
95	  if (itemPath === null || !isElement(element)) return;
96	  const current = element["checked"] === true;
97	  const newChecked = !current;
98	  const existingId = findTaskId(element);
99	
100	  if (existingId === null) {
101	    const id = crypto.randomUUID();
102	    editor.tf.setNodes({ checked: newChecked, taskOriginal: current }, { at: itemPath });
103	    setLeafMarks(editor, itemPath, element, { task: true, [`task_${id}`]: true });
104	    return;
105	  }
106	
107	  const original = element["taskOriginal"] === true;
108	  if (newChecked === original) {
109	    unsetLeafMarks(editor, itemPath, element, ["task", `task_${existingId}`]);
110	    editor.tf.setNodes({ checked: newChecked, taskOriginal: null }, { at: itemPath });
111	    return;
112	  }
113	  editor.tf.setNodes({ checked: newChecked }, { at: itemPath });
114	};
115	
116	/** First top-level block carrying a `task_<id>` mark, with its index, or null. */
117	const findTaskItem = (
118	  children: readonly unknown[],
119	  id: string
120	): { node: ElementNode; index: number } | null => {
121	  for (const [index, node] of children.entries()) {
122	    if (isElement(node) && findTaskId(node) === id) return { node, index };
123	  }
124	  return null;
125	};
126	
127	/**
128	 * Remove a task toggle (sidebar "remove"): drop the `task` / `task_<id>` marks
129	 * and restore the item's `checked` to its pre-toggle `taskOriginal`, mirroring
130	 * the toggle-back-to-original branch of {@link applyTaskToggle}.
131	 */
132	export const removeTaskToggle = (editor: PlateEditor, id: string): void => {
133	  const match = findTaskItem(editor.children, id);
134	  if (match === null) return;
135	  const itemPath = [match.index];
136	  unsetLeafMarks(editor, itemPath, match.node, ["task", `task_${id}`]);
137	  editor.tf.setNodes(
138	    { checked: match.node["taskOriginal"] === true, taskOriginal: null },
139	    { at: itemPath }
140	  );
141	};
