144	function stripUnparseableBlocks(css: string): string {
145	  const withoutImports = css.replace(/^\s*@import\b[^;]*;\s*$/gm, "");
146	  const withoutCustomVariants = withoutImports.replace(/^\s*@custom-variant\s+[^;]+;\s*$/gm, "");
147	  return stripAtThemeBlocks(withoutCustomVariants);
148	}
149	
150	function stripAtThemeBlocks(css: string): string {
151	  let out = css;
152	  while (true) {
153	    const start = out.search(/@theme\s+inline\s*\{/);
154	    if (start === -1) {
155	      return out;
156	    }
157	    const openBrace = out.indexOf("{", start);
158	    if (openBrace === -1) {
159	      return out;
160	    }
161	    const end = findMatchingBrace(out, openBrace);
162	    if (end === -1) {
163	      return out;
164	    }
165	    out = `${out.slice(0, start)}${out.slice(end + 1)}`;
166	  }
167	}
168	
169	function findMatchingBrace(source: string, openIndex: number): number {
170	  let depth = 1;
171	  let i = openIndex + 1;
172	  while (i < source.length && depth > 0) {
173	    const ch = source.charAt(i);
174	    if (ch === "{") {
175	      depth += 1;
176	    } else if (ch === "}") {
177	      depth -= 1;
178	    }
179	    i += 1;
180	  }
181	  return depth === 0 ? i - 1 : -1;
182	}
183	
184	function parseOklch(value: string): Oklch {
185	  const match = /^oklch\(\s*([0-9.]+)\s+([0-9.]+)\s+([0-9.]+)\s*\)$/.exec(value);
186	  const lRaw = match?.[1];
187	  const cRaw = match?.[2];
188	  const hRaw = match?.[3];
189	  if (lRaw === undefined || cRaw === undefined || hRaw === undefined) {
190	    throw new Error(`Unsupported OKLCH form: ${value}`);
191	  }
192	  return { l: Number(lRaw), c: Number(cRaw), h: Number(hRaw) };
193	}
194	
195	function oklchToOklab({ l, c, h }: Oklch): Oklab {
196	  const rad = (h * Math.PI) / 180;
197	  return { l, a: c * Math.cos(rad), b: c * Math.sin(rad) };
198	}
199	
200	function oklabToLinearSrgb({ l, a, b }: Oklab): LinearRgb {
201	  const lCubeRoot = l + 0.3963377774 * a + 0.2158037573 * b;
202	  const mCubeRoot = l - 0.1055613458 * a - 0.0638541728 * b;
203	  const sCubeRoot = l - 0.0894841775 * a - 1.291485548 * b;
204	
205	  const lLong = lCubeRoot ** 3;
206	  const mLong = mCubeRoot ** 3;
207	  const sLong = sCubeRoot ** 3;
208	
209	  return [
210	    4.0767416621 * lLong - 3.3077115913 * mLong + 0.2309699292 * sLong,
211	    -1.2684380046 * lLong + 2.6097574011 * mLong - 0.3413193965 * sLong,
212	    -0.0041960863 * lLong - 0.7034186147 * mLong + 1.707614701 * sLong,
213	  ];
214	}
215	
216	function linearRgbFromOklch(value: string): LinearRgb {
217	  return oklabToLinearSrgb(oklchToOklab(parseOklch(value)));
218	}
219	
220	function luminance([r, g, b]: LinearRgb): number {
221	  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
222	}
223	
224	function contrastRatio(l1: number, l2: number): number {
225	  const lighter = Math.max(l1, l2);
226	  const darker = Math.min(l1, l2);
227	  return (lighter + 0.05) / (darker + 0.05);
228	}
