import { expect } from "@playwright/test";

import { Given, Then } from "../support/bdd.ts";

/**
 * A draft exactly as an older build persisted it: the reviewer had ticked the
 * "Open task" checkbox, so `applyTaskToggle` flipped `checked`, snapshotted the
 * pre-toggle state in `taskOriginal`, and tagged the item's text with the
 * `task` / `task_<id>` marks the annotation walker reads. The checkbox is gone,
 * but this shape is frozen on disk for anyone who used it — the viewer still has
 * to surface and clear it.
 */
const legacyDraftValue = [
  { type: "h1", children: [{ text: "Task list" }] },
  {
    type: "p",
    listStyleType: "todo",
    indent: 1,
    checked: true,
    taskOriginal: false,
    children: [{ text: "Open task", task: true, task_legacy1: true }],
  },
  {
    type: "p",
    listStyleType: "todo",
    indent: 1,
    checked: true,
    children: [{ text: "Completed task" }],
  },
];

Given("a draft persisted by an older build carries a task toggle", async ({ page, annotateUrl }) => {
  const response = await page.request.post(new URL("api/draft", annotateUrl).toString(), {
    data: {
      value: legacyDraftValue,
      commentBodies: {},
      globalComments: [],
      updatedAt: 1_700_000_000_000,
    },
  });
  expect(response.ok()).toBe(true);
});

Then("the annotation sidebar shows a task entry {string}", async ({ page }, body: string) => {
  await expect(
    page.locator('[data-testid^="sidebar-entry-"][data-kind="task"]', { hasText: body })
  ).toHaveCount(1);
});

Then("the annotation sidebar is empty", async ({ page }) => {
  await expect(page.locator('[data-testid^="sidebar-entry-"]')).toHaveCount(0);
});

Then("the task item {string} is struck through", async ({ page }, text: string) => {
  await expect(
    page.locator('[data-testid="editor-list"][data-checked="true"]', { hasText: text })
  ).toHaveCount(1);
});

Then("the task item {string} is not struck through", async ({ page }, text: string) => {
  await expect(
    page.locator('[data-testid="editor-list"][data-checked="false"]', { hasText: text })
  ).toHaveCount(1);
});

